import { loadFont as loadHead } from "@remotion/google-fonts/BarlowCondensed";
import { loadFont as loadTxt } from "@remotion/google-fonts/Montserrat";
import React, { createContext, useContext } from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// DIRETO DO DONO — versão 2, limpa. Pedido: "muita poluição visual e glow desnecessário, preciso de algo mais clean,
// usando o fundo preto e branco, glow leve com destaque nos lugares certos". Aqui: cenas alternando fundo preto e fundo
// branco lisos (logo branca / logo preta), verde só como destaque, nenhum enfeite de fundo, e brilho suave em um único
// elemento por cena (a palavra-chave ou o botão ativo). Mesma locução e mesmos tempos da versão 1 (palavra + 0,15 s).

const { fontFamily: HEAD } = loadHead("italic", { weights: ["700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: TXT } = loadTxt("normal", { weights: ["400", "600", "700"], subsets: ["latin", "latin-ext"] });

export const DD2_FPS = 30;
export const DD2_GAP = 3.51; // duração interna da vitrine dos carros (ela é esticada para o tempo da frase "olha só os carros…")
// Locução nova (Roberta, 39,2 s). As cenas continuam escritas no tempo da locução antiga; WARP leva o tempo do vídeo para
// esse tempo antigo, palavra por palavra: [tempo no vídeo, tempo antigo]. Em 10,60–13,20 s o tempo antigo para: é a vitrine.
const WARP: [number, number][] = [[0,0],[0.28,0.27],[0.6,0.56],[0.9,0.78],[1.14,1.0],[1.9,1.96],[2.04,2.1],[2.67,2.98],[3.17,3.42],[3.39,4.22],[3.93,4.62],[4.63,5.24],[4.77,5.32],[5.15,5.64],[5.45,5.88],[5.95,6.66],[6.25,6.98],[6.51,7.43],[7.13,8.35],[7.43,8.63],[7.65,9.17],[8.07,9.49],[9.13,10.43],[9.52,10.79],[10.08,11.43],[10.49,11.9],[10.6,12.21],[13.2,12.21],[13.28,12.39],[13.82,12.85],[14.52,13.87],[15.08,14.3],[15.48,14.95],[16.17,15.55],[16.87,16.61],[17.61,17.17],[17.96,17.51],[18.17,18.23],[19.05,19.15],[19.37,19.39],[20.09,19.99],[20.85,20.59],[21.19,20.89],[21.41,21.41],[21.91,21.85],[22.41,22.35],[22.69,22.77],[23.37,23.43],[23.82,23.83],[24.1,24.59],[24.68,25.17],[25.24,25.92],[25.68,26.22],[26.78,27.15],[27.14,27.5],[27.74,28.06],[28.34,28.66],[28.52,28.76],[29.06,29.62],[29.52,29.94],[29.78,30.6],[30.54,31.58],[31.2,32.12],[31.76,32.7],[32.77,33.78],[33.73,34.68],[33.97,35.56],[34.63,36.04],[35.41,36.78],[35.85,37.14],[36.39,38.04],[36.9,38.4],[37.11,38.94],[37.57,39.24],[37.77,39.74],[38.27,40.41],[38.91,41.37],[39.2,41.75],[42.0,44.55]];
const SHOW_A = 10.6;
const SHOW_B = 13.2;
export const DD2_FRAMES = Math.round(42.0 * DD2_FPS);
const G = "#14D214";
const INK = "#0A0A0A";
const PAPER = "#F4F4F1";

type Tone = "k" | "w" | "g";
const ToneCtx = createContext<Tone>("k");
const TH = {
  k: { bg: "#070707", bg2: "#161616", fg: "#FFFFFF", sub: "#8E938E", card: "#111111", line: "#2E2E2E", hl: G, shadow: "0 30px 70px rgba(0,0,0,0.6)" },
  w: { bg: PAPER, bg2: "#E3E4DF", fg: INK, sub: "#6C716C", card: "#FFFFFF", line: "#D5D7D2", hl: "#10B310", shadow: "0 24px 60px rgba(0,0,0,0.12)" },
  g: { bg: G, bg2: "#11C011", fg: INK, sub: "#0A3D0A", card: "#FFFFFF", line: INK, hl: "#FFFFFF", shadow: "0 24px 60px rgba(0,0,0,0.2)" },
};
const useTh = () => TH[useContext(ToneCtx)];

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const k = (t: number, a: number, d = 0.35) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const slam = (t: number, at: number, d = 0.26): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
  return { opacity: t >= at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.7 - 0.7 * e).toFixed(3)})` };
};
const rise = (t: number, at: number, dy = 70, d = 0.45): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
  return { opacity: e, transform: `translateY(${((1 - e) * dy).toFixed(1)}px)` };
};
const side = (t: number, at: number, dx = -260, d = 0.45): React.CSSProperties => {
  const e = interpolate(t, [at, at + d], [0, 1], { ...cl, easing: OUT });
  return { opacity: Math.min(1, e * 2.5), transform: `translateX(${((1 - e) * dx).toFixed(1)}px)` };
};
const SOFT = "0 0 30px rgba(20,210,20,0.4)"; // o único brilho: leve, e só no destaque da cena
const fit = (s: string, size: number, max = 900) => Math.min(size, max / (s.length * 0.455));
const hs = (size: number, color: string): React.CSSProperties => ({ fontFamily: HEAD, fontStyle: "italic", fontWeight: 800, fontSize: size, lineHeight: 0.92, color, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "0.005em" });
const col = (top: number, gap = 10): React.CSSProperties => ({ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap });
const Hd: React.FC<{ children: string; size: number; hl?: boolean; soft?: boolean; color?: string; style?: React.CSSProperties }> = ({ children, size, hl, soft, color, style }) => {
  const th = useTh();
  return <div style={{ ...hs(fit(children, size), color ?? (hl ? th.hl : th.fg)), textShadow: soft ? SOFT : "none", ...style }}>{children}</div>;
};
const Small: React.FC<{ children: string; style?: React.CSSProperties }> = ({ children, style }) => {
  const th = useTh();
  return <div style={{ fontFamily: TXT, fontWeight: 600, fontSize: 38, color: th.fg, letterSpacing: "0.3em", textTransform: "uppercase", whiteSpace: "nowrap", ...style }}>{children}</div>;
};
// etiqueta em paralelogramo verde, como o "CHAME AGORA" das artes
const Tag: React.FC<{ children: string; size?: number }> = ({ children, size = 64 }) => (
  <div style={{ background: G, transform: "skewX(-14deg)", padding: `${size * 0.14}px ${size * 0.5}px ${size * 0.18}px`, borderRadius: 8 }}>
    <div style={{ ...hs(size, INK), transform: "skewX(14deg)" }}>{children}</div>
  </div>
);
const Rule: React.FC<{ w: number }> = ({ w }) => <div style={{ height: 5, width: w, background: G, transform: "skewX(-30deg)" }} />;

// ───────── cena: fundo liso (preto ou branco) com uma luz muito suave se deslocando; a câmera aproxima devagar ─────────
const Sc: React.FC<{ t: number; a: number; b: number; tone: Tone; bg?: React.ReactNode; children: React.ReactNode }> = ({ t, a, b, tone, bg, children }) => {
  if (t < a || t >= b) return null;
  const th = TH[tone];
  return (
    <ToneCtx.Provider value={tone}>
      <AbsoluteFill style={{ overflow: "hidden", background: th.bg }}>
        {bg ?? <AbsoluteFill style={{ background: `radial-gradient(ellipse 90% 60% at ${(50 + Math.sin(t * 1.25) * 42).toFixed(1)}% ${(40 + Math.cos(t * 0.9) * 26).toFixed(1)}%, ${{ k: "#262626", w: "#FFFFFF", g: "#4BEA4B" }[tone]} 0%, ${{ k: th.bg, w: "#D9DAD5", g: "#11C011" }[tone]} 78%)` }} />}
        <AbsoluteFill style={{ transform: `scale(${(0.97 + 0.03 * lin(t, a, Math.min(b, a + 6.4))).toFixed(4)})`, transformOrigin: "50% 32%" }}>{children}</AbsoluteFill>
      </AbsoluteFill>
    </ToneCtx.Provider>
  );
};
// troca de cena: o fundo da cena seguinte entra inclinado, com um fio verde na borda
type Kind = "skew" | "up" | "iris" | "split" | "none";
const Cut: React.FC<{ t: number; at: number; i: number; tone: Tone; d?: number; kind?: Kind }> = ({ t, at, i, tone, d = 0.2, kind = "skew" }) => {
  if (kind === "none" || t < at - d || t > at + d) return null;
  const bg = TH[tone].bg;
  const dir = i % 2 ? -1 : 1;
  if (kind === "up") {
    // o fundo da cena seguinte sobe (ou desce) e passa
    const y = (1 - lin(t, at - d, at + d) * 2) * 2400 * dir;
    return <div style={{ position: "absolute", left: -100, top: -200, width: 1280, height: 2320, background: bg, transform: `translateY(${y.toFixed(0)}px)`, boxShadow: `0 18px 0 ${G}, 0 -18px 0 ${G}` }} />;
  }
  if (kind === "iris") {
    // um círculo abre do centro até cobrir a tela
    return t < at ? <div style={{ position: "absolute", left: 540 - 1300, top: 960 - 1300, width: 2600, height: 2600, borderRadius: 1300, background: bg, boxShadow: `0 0 0 16px ${G}`, transform: `scale(${interpolate(t, [at - d, at], [0, 1], { ...cl, easing: Easing.in(Easing.quad) }).toFixed(4)})` }} /> : null;
  }
  if (kind === "split") {
    // duas metades fecham no meio e abrem de novo
    const c = t < at ? interpolate(t, [at - d, at], [0, 1], { ...cl, easing: OUT }) : 1 - interpolate(t, [at, at + d], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
    return (
      <>
        <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 962, background: bg, borderBottom: `10px solid ${G}`, boxSizing: "border-box", transform: `translateY(${((c - 1) * 980).toFixed(0)}px)` }} />
        <div style={{ position: "absolute", left: 0, top: 958, width: 1080, height: 962, background: bg, borderTop: `10px solid ${G}`, boxSizing: "border-box", transform: `translateY(${((1 - c) * 980).toFixed(0)}px)` }} />
      </>
    );
  }
  const x = (lin(t, at - d, at + d) * 2 - 1) * 2000 * dir;
  return <div style={{ position: "absolute", left: 540 - 900, top: -200, width: 1800, height: 2320, background: bg, transform: `translateX(${x.toFixed(0)}px) skewX(${-16 * dir}deg)`, boxShadow: `${18 * dir}px 0 0 ${G}, ${-18 * dir}px 0 0 ${G}` }} />;
};
const Pin: React.FC<{ s: number }> = ({ s }) => {
  const th = useTh();
  return (
    <svg width={s} height={s * 1.3} viewBox="0 0 30 39">
      <path d="M15 1C7.300 1 1 7.300 1 15c0 10 14 23 14 23s14-13 14-23C29 7.300 22.700 1 15 1z" fill={G} />
      <circle cx={15} cy={15} r={5.500} fill={th.bg} />
    </svg>
  );
};
const Cursor: React.FC<{ x: number; y: number; press?: number; show?: boolean }> = ({ x, y, press = 0, show = true }) => (
  <svg width={130} height={148} viewBox="0 0 30 34" style={{ position: "absolute", left: x, top: y, opacity: show ? 1 : 0, transform: `scale(${(1 - press * 0.16).toFixed(3)})`, transformOrigin: "10% 5%", filter: "drop-shadow(0 8px 12px rgba(0,0,0,0.35))" }}>
    <path d="M3 2 L3 25 L9 19.500 L13.500 30 L18 28 L13.500 18 L22 18 Z" fill="#FFFFFF" stroke={INK} strokeWidth={2} strokeLinejoin="round" />
  </svg>
);
const Avatar: React.FC<{ s: number }> = ({ s }) => (
  <div style={{ width: s, height: s, borderRadius: s / 2, background: INK, border: `${Math.max(4, s * 0.03)}px solid ${G}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
    <Img src={staticFile("dd/marca.png")} style={{ height: s * 0.52 }} />
  </div>
);
const Logo: React.FC<{ t: number; at: number; w: number }> = ({ t, at, w }) => {
  const tone = useContext(ToneCtx);
  const e = interpolate(t, [at, at + 0.7], [0, 1], { ...cl, easing: OUT });
  return (
    <div style={{ width: w, height: w * (356 / 2089), clipPath: `inset(-20% ${((1 - e) * 100).toFixed(1)}% -20% 0)`, transform: `scale(${(1.08 - 0.08 * e).toFixed(4)})` }}>
      <Img src={staticFile(tone === "k" ? "dd/logo.png" : "dd/logo-preta.png")} style={{ width: w, display: "block" }} />
    </div>
  );
};
const Photo: React.FC<{ src: string; t: number; a: number; b: number; from?: number; to?: number; pos?: string; style?: React.CSSProperties }> = ({ src, t, a, b, from = 1.06, to = 1.2, pos = "50% 50%", style }) => (
  <Img src={staticFile(`dd/${src}`)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: pos, transform: `scale(${(from + (to - from) * lin(t, a, b)).toFixed(4)})`, ...style }} />
);
const ICON = { fill: "none", stroke: "currentColor", strokeWidth: 2.200, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
const IcLink = (s: number) => (
  <svg width={s} height={s} viewBox="0 0 24 24" {...ICON}>
    <path d="M10 14a4.500 4.500 0 0 0 6.400 0l3.200-3.200a4.500 4.500 0 0 0-6.400-6.400L12 5.600M14 10a4.500 4.500 0 0 0-6.400 0l-3.200 3.200a4.500 4.500 0 0 0 6.400 6.400L12 18.400" />
  </svg>
);
const IcFollow = (s: number) => (
  <svg width={s} height={s} viewBox="0 0 24 24" {...ICON}>
    <circle cx={9.500} cy={8} r={4} />
    <path d="M2.500 20.500c0-3.900 3.100-6.500 7-6.500s7 2.600 7 6.500M19 7v6M16 10h6" />
  </svg>
);
const IcSend = (s: number) => (
  <svg width={s} height={s} viewBox="0 0 24 24" {...ICON}>
    <path d="M21.500 2.500L10.500 13.500M21.500 2.500l-7 19-4-9-9-4z" />
  </svg>
);
const IcUser = (s: number) => (
  <svg width={s} height={s} viewBox="0 0 24 24" {...ICON}>
    <circle cx={12} cy={8} r={4.200} />
    <path d="M4 21c0-4.400 3.600-7 8-7s8 2.600 8 7" />
  </svg>
);
const IcCheck = (s: number, c = "currentColor") => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={3.400} strokeLinecap="round" strokeLinejoin="round">
    <path d="M4.500 12.500l5 5L19.500 7" />
  </svg>
);
const WaIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 48 48">
    <circle cx={24} cy={24} r={24} fill="#25D366" />
    <path d="M24 9a15 15 0 0 0-12.800 22.800L9 39l7.500-2.100A15 15 0 1 0 24 9z" fill="#FFFFFF" />
    <path d="M19 16.500c-.400-.800-.800-.800-1.100-.800h-1c-.400 0-.900.100-1.400.700-.500.500-1.800 1.700-1.800 4.200s1.800 4.900 2.100 5.300c.200.300 3.500 5.600 8.700 7.600 4.300 1.700 5.200 1.400 6.100 1.300.900-.100 3-1.200 3.400-2.400.400-1.200.400-2.200.300-2.400-.100-.200-.400-.300-1-.600l-3.400-1.600c-.500-.200-.800-.200-1.100.200-.400.500-1.300 1.600-1.600 2-.300.300-.600.400-1.100.100-.500-.200-2.100-.800-4.100-2.500-1.500-1.300-2.500-3-2.800-3.500-.300-.500 0-.800.200-1 .200-.200.500-.600.800-.900.200-.300.300-.500.500-.800.200-.400.100-.700-.100-.900z" fill="#25D366" />
  </svg>
);
const Arrows: React.FC<{ t: number; from: number; c?: string; s?: number }> = ({ t, from, c = G, s = 1 }) => (
  <div style={{ display: "flex", gap: 70, height: 80, opacity: t > from ? 1 : 0 }}>
    {[0, 1, 2].map((i) => {
      const u = ((t - from) * 2 + i * 0.33) % 1;
      return (
        <svg key={i} width={90 * s} height={58 * s} viewBox="0 0 28 18" fill="none" stroke={c} strokeWidth={5} strokeLinecap="round" strokeLinejoin="round" style={{ opacity: Math.sin(u * Math.PI), transform: `translateY(${(u * 60).toFixed(0)}px)` }}>
          <path d="M3 3l11 11L25 3" />
        </svg>
      );
    })}
  </div>
);
// um único anel fino, só nos dois "ACABOU."
const Ring: React.FC<{ t: number; at: number; y: number }> = ({ t, at, y }) => {
  const u = lin(t, at, at + 0.8);
  return u > 0 && u < 1 ? <div style={{ position: "absolute", left: 540 - 500, top: y - 500, width: 1000, height: 1000, borderRadius: 500, border: `4px solid ${G}`, boxSizing: "border-box", opacity: 0.8 * (1 - u), transform: `scale(${(0.2 + u * 1.3).toFixed(3)})` }} /> : null;
};

// trocas de cena, com o fundo de cada cena
const C = { s2: 4.05, logo: 7.25, s3: 9.02, s4: 12.22, s5: 14.72, s6: 18.02, s7: 24.38, s8: 30.42, s9: 35.32, s10: 38.78, end: 40.3 };
const Q = { voce: 1.0, pin: 1.9, dif: 4.6, vender: 5.22, aqui: 6.58 }; // batidas dentro dos primeiros 7 s
const CUTS: [number, Tone, number?, Kind?][] = [
  [Q.voce, "w", 0.12, "up"], [Q.pin, "k", 0.13, "skew"], [Q.dif, "k", 0.11, "none"], [Q.vender, "w", 0.11, "up"], [Q.aqui, "g", 0.13, "iris"],
  [C.s2, "w", 0.2, "split"], [C.logo, "k", 0.2, "skew"], [C.s3, "w", 0.2, "up"], [C.s5, "k", 0.2, "skew"], [C.s6, "w", 0.22, "iris"], [C.s7, "k", 0.2, "split"],
  [C.s8, "w", 0.2, "up"], [C.s9, "k", 0.2, "skew"], [C.s10, "w", 0.22, "iris"], [C.end, "k", 0.2, "split"],
]; // a troca para "Tá difícil vender?" (C.s4) é feita pela vitrine dos carros

// 1 — "Esse vídeo é pra você, de Itabuna e região." em três batidas: preto, branco, preto
const S1: React.FC<{ t: number }> = ({ t }) => {
  const drop = interpolate(t, [1.94, 2.24], [0, 1], { ...cl, easing: Easing.bounce });
  return (
    <>
      <Sc t={t} a={0} b={Q.voce} tone="k">
        <div style={col(740, 6)}>
          <div style={{ display: "flex", gap: 30 }}>
            <div style={slam(t, 0.3, 0.18)}>
              <Hd size={196}>Esse</Hd>
            </div>
            <div style={slam(t, 0.56, 0.18)}>
              <Hd size={196}>vídeo</Hd>
            </div>
          </div>
          <div style={slam(t, 0.78, 0.18)}>
            <Hd size={196}>é pra</Hd>
          </div>
        </div>
      </Sc>
      <Sc t={t} a={Q.voce} b={Q.pin} tone="w">
        <div style={col(610, 14)}>
          <Small style={rise(t, 1.02, 30, 0.25)}>Esse vídeo é pra</Small>
          <div style={slam(t, 1.0, 0.2)}>
            <Hd size={430}>Você</Hd>
          </div>
          <div style={{ height: 26, width: 780 * k(t, 1.18, 0.4), background: G, transform: "skewX(-30deg)" }} />
        </div>
      </Sc>
      <Sc t={t} a={Q.pin} b={C.s2} tone="k">
        {[0, 0.5].map((dl) => {
          const u = t > 2.22 ? ((t - 2.22) * 0.8 + dl) % 1 : -1;
          return u >= 0 ? <div key={dl} style={{ position: "absolute", left: 540 - 260, top: 832 - 64, width: 520, height: 128, borderRadius: "50%", border: `3px solid ${G}`, boxSizing: "border-box", opacity: 0.65 * (1 - u), transform: `scale(${(0.2 + u * 1.4).toFixed(3)})` }} /> : null;
        })}
        <div style={{ position: "absolute", left: 540 - 80, top: 630 - (1 - drop) * 900, opacity: t >= 1.94 ? 1 : 0 }}>
          <Pin s={160} />
        </div>
        <div style={col(940)}>
          <div style={slam(t, 2.1, 0.2)}>
            <Hd size={196}>De Itabuna</Hd>
          </div>
        </div>
        {/* faixa verde atravessando a tela */}
        <div style={{ position: "absolute", left: -300, top: 1170, width: 1680, height: 214, background: G, display: "flex", alignItems: "center", justifyContent: "center", transform: `translateX(${((1 - k(t, 2.86, 0.4)) * -1900).toFixed(0)}px) skewY(-3deg)` }}>
          <div style={{ ...hs(176, INK), transform: `scale(${pop(t, 2.98, 0.32).toFixed(3)})` }}>e região</div>
        </div>
      </Sc>
    </>
  );
};
// 2 — "Você que tem dificuldade em vender o seu carro… aqui, ó:" em quatro batidas: branco, preto, branco, verde
const S2: React.FC<{ t: number }> = ({ t }) => {
  const j = t > 4.62 ? 9 * Math.max(0, 1 - (t - 4.62) / 0.4) : 0;
  const th = TH.w;
  const fall = interpolate(t, [5.95, 6.3], [0, 1], { ...cl, easing: OUT });
  return (
    <>
      <Sc t={t} a={C.s2} b={Q.dif} tone="w">
        <div style={col(850)}>
          <div style={slam(t, 4.2, 0.18)}>
            <Hd size={170}>Você que tem</Hd>
          </div>
        </div>
      </Sc>
      <Sc t={t} a={Q.dif} b={Q.vender} tone="k">
        <div style={{ ...col(850), transform: `translate(${(Math.sin(t * 71) * j).toFixed(1)}px, ${(Math.cos(t * 53) * j * 0.6).toFixed(1)}px)` }}>
          <div style={slam(t, 4.62, 0.18)}>
            <Hd size={200} style={{ transform: "rotate(-3deg)" }}>
              Dificuldade
            </Hd>
          </div>
