// vitrine dos carros: os prints do Instagram do cliente em destaque, um por batida da trilha (92 BPM)
const SHOW: [string, number][] = [["frontier", 0], ["compass", 0.9], ["tracker", 1.55], ["hrv", 2.2], ["strada", 2.86]];
const Showcase: React.FC<{ u: number }> = ({ u }) => {
  const inn = interpolate(u, [0, 0.26], [0, 1], { ...cl, easing: OUT });
  const out = interpolate(u, [DD2_GAP - 0.2, DD2_GAP], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  const cur = SHOW.reduce((m, [, at], i) => (u >= at ? i : m), 0);
  return (
    <AbsoluteFill style={{ background: "#070707", transform: `translateY(${((1 - inn) * 1920).toFixed(0)}px)`, overflow: "hidden" }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: 150, display: "flex", justifyContent: "center", alignItems: "center", gap: 22, opacity: 1 - out }}>
        <Avatar s={96} />
        <div style={{ fontFamily: TXT, fontWeight: 700, fontSize: 46, color: "#FFFFFF" }}>@suamarca</div>
      </div>
      {SHOW.map(([name, at], i) => {
        if (i > cur || i < cur - 1 || (i === cur - 1 && u > SHOW[cur][1] + 0.3)) return null; // o anterior só fica enquanto o novo entra
        const e = interpolate(u, [at, at + 0.24], [0, 1], { ...cl, easing: OUT });
        const land = 1 + 0.045 * (u >= at + 0.2 ? 1 - interpolate(u, [at + 0.2, at + 0.5], [0, 1], { ...cl, easing: OUT }) : 0);
        const from = [`translateY(${(1 - e) * 1900}px)`, `translateX(${(1 - e) * 1250}px) rotate(${(1 - e) * 9}deg)`, `scale(${0.35 + 0.65 * e})`, `translateX(${(1 - e) * -1250}px) rotate(${(1 - e) * -9}deg)`, `translateY(${(1 - e) * -1900}px)`][i];
        return (
          <div key={name} style={{ position: "absolute", left: 60, top: 320, width: 960, height: 1204, borderRadius: 44, overflow: "hidden", border: "6px solid #FFFFFF", boxSizing: "border-box", opacity: i === 2 ? e : 1, transform: `${from} scale(${land.toFixed(4)}) translateY(${(i === cur ? out * -2000 : 0).toFixed(0)}px)`, boxShadow: "0 40px 90px rgba(0,0,0,0.7)" }}>
            <Img src={staticFile(`dd/post-${name}.jpg`)} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
          </div>
        );
      })}
      <div style={{ position: "absolute", left: 0, right: 0, top: 1580, display: "flex", justifyContent: "center", gap: 16, opacity: 1 - out }}>
        {SHOW.map(([name], i) => (
          <div key={name} style={{ width: i === cur ? 70 : 22, height: 22, borderRadius: 11, background: i === cur ? G : "#3A3A3A" }} />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export const DiretoDoDono2: React.FC = () => {
  const f = useCurrentFrame();
  const tr = f / DD2_FPS;
  const show = tr >= SHOW_A && tr < SHOW_B;
  const t = interpolate(tr, WARP.map((w) => w[0]), WARP.map((w) => w[1]), cl);
  return (
    <AbsoluteFill style={{ background: "#070707" }}>
      <S1 t={t} />
      <S2 t={t} />
      <SLogo t={t} />
      <S3 t={t} />
      <S4 t={t} />
      <S5 t={t} />
      <S6 t={t} />
      <S7 t={t} />
      <S8 t={t} />
      <S9 t={t} />
      <S10 t={t} />
      <SEnd t={t} />
      {CUTS.map(([at, tone, d, kind], i) => (
        <Cut key={i} t={t} at={at} i={i} tone={tone} d={d} kind={kind} />
      ))}
      {show ? <Showcase u={((tr - SHOW_A) / (SHOW_B - SHOW_A)) * DD2_GAP} /> : null}
      {/* abertura: o branco sai da tela e revela o preto */}
      {t < 0.24 ? <div style={{ position: "absolute", left: -360, top: -200, width: 1800, height: 2320, background: PAPER, transform: `translateX(${(lin(t, 0, 0.24) * 2000).toFixed(0)}px) skewX(-16deg)`, boxShadow: `-18px 0 0 ${G}` }} /> : null}
    </AbsoluteFill>
  );
};

